<?php
namespace App\Http\Controllers;
use App\Models\{PatientFollowup as Followup,FollowupEvent as Event,Customer,User,Service,Company};
use App\Services\{FollowupScheduling,Availability,AppointmentReminder};
use App\Support\Followups;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\{Rule,ValidationException};
class FollowupController extends Controller {
 private function authorize(Request $r):void{app(FollowupScheduling::class)->authorize($r);}
 private function lock(Request $r):void{Company::whereKey($r->user()->company_id)->lockForUpdate()->firstOrFail();$u=User::whereKey($r->user()->id)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->company_id===$r->user()->company_id&&($u->isOwner()||$u->isReception()),403);}
 private function view(string $name,array $data){return response()->view('followups.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function find(Request $r,int $id):Followup{return app(FollowupScheduling::class)->find($r,$id);}
 private function event(Request $r,Followup $f,string $kind,array $payload=[],?string $key=null):void{Event::create(['company_id'=>$f->company_id,'followup_id'=>$f->id,'actor_id'=>$r->user()->id,'event'=>$kind,'payload'=>$payload,'request_key'=>$key]);}
 private function fail(string $msg):never{throw ValidationException::withMessages(['revision'=>$msg]);}
 private function fields(Request $r):array{return $r->validate(['customer_id'=>'required|integer','professional_id'=>'nullable|integer','service_id'=>'nullable|integer','kind'=>['required',Rule::in(array_keys(Followups::KINDS))],'from_date'=>'required|date_format:Y-m-d|after_or_equal:1900-01-01|before_or_equal:2100-01-01','to_date'=>'nullable|date_format:Y-m-d|after_or_equal:from_date|before_or_equal:2100-01-01','period'=>['required',Rule::in(array_keys(Followups::PERIODS))],'note'=>'nullable|string|max:500']);}
 private function checkReferences(Request $r,array $d):void{Customer::where('company_id',$r->user()->company_id)->where('active',true)->findOrFail($d['customer_id']);if(!empty($d['professional_id']))User::where('company_id',$r->user()->company_id)->where('role','professional')->where('active',true)->findOrFail($d['professional_id']);if(!empty($d['service_id']))Service::where('company_id',$r->user()->company_id)->where('active',true)->findOrFail($d['service_id']);}
 public function index(Request $r){$this->authorize($r);$r->validate(['kind'=>['nullable',Rule::in(array_keys(Followups::KINDS))],'state'=>'nullable|in:open,pending,contacted,scheduled,closed,all','until'=>'nullable|date_format:Y-m-d','professional_id'=>'nullable|integer']);$today=app(Availability::class)->localNow($r->user()->company)->toDateString();$until=$r->input('until')?:app(Availability::class)->localNow($r->user()->company)->addDays(30)->toDateString();$q=Followup::where('company_id',$r->user()->company_id)->with(['customer','professional','service','appointment'])->whereDate('from_date','<=',$until);$state=$r->input('state','open');if($state==='open')$q->whereIn('status',['pending','contacted']);elseif($state!=='all')$q->where('status',$state);if($r->filled('kind'))$q->where('kind',$r->input('kind'));$professionals=User::where('company_id',$r->user()->company_id)->where('role','professional')->orderBy('name')->get();if($r->filled('professional_id')){abort_unless($professionals->contains('id',$r->integer('professional_id')),404);$q->where('professional_id',$r->integer('professional_id'));}$entries=$q->orderBy('from_date')->orderBy('id')->paginate(20)->withQueryString();return $this->view('index',compact('entries','today','until','professionals'));}
 private function form(Request $r,?Followup $entry){$customers=Customer::where('company_id',$r->user()->company_id)->where(function($q)use($entry){$q->where('active',true);if($entry?->customer_id)$q->orWhere('id',$entry->customer_id);})->orderBy('name')->get();$professionals=User::where('company_id',$r->user()->company_id)->where('role','professional')->where(function($q)use($entry){$q->where('active',true);if($entry?->professional_id)$q->orWhere('id',$entry->professional_id);})->orderBy('name')->get();$services=Service::where('company_id',$r->user()->company_id)->where(function($q)use($entry){$q->where('active',true);if($entry?->service_id)$q->orWhere('id',$entry->service_id);})->orderBy('name')->get();$today=app(Availability::class)->localNow($r->user()->company)->toDateString();return $this->view('form',compact('entry','customers','professionals','services','today'));}
 public function create(Request $r){$this->authorize($r);return $this->form($r,null);}
 public function edit(Request $r,int $id){$entry=$this->find($r,$id);abort_unless($entry->isOpen(),422,'Somente solicitações abertas podem ser revisadas.');return $this->form($r,$entry);}
 public function store(Request $r){$this->authorize($r);$r->validate(['request_id'=>'required|uuid']);$d=$this->fields($r);$id=DB::transaction(function()use($r,$d){$this->lock($r);$key=hash('sha256','followup|'.$r->user()->company_id.'|'.$r->user()->id.'|'.$r->input('request_id'));if($old=Followup::where('request_key',$key)->first()){abort_unless((int)$old->customer_id===(int)$d['customer_id'],409);return $old->id;}$this->checkReferences($r,$d);$f=Followup::create($d+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id,'request_key'=>$key]);$this->event($r,$f,'created',$d);return $f->id;},3);return redirect()->route('followups.show',$id)->with('success','Solicitação registrada. Ela ainda não reserva um horário na agenda.');}
 public function update(Request $r,int $id){$this->authorize($r);$r->validate(['revision'=>'required|integer']);$d=$this->fields($r);DB::transaction(function()use($r,$id,$d){$this->lock($r);$f=$this->find($r,$id);if(!$f->isOpen()||$f->revision!==$r->integer('revision'))$this->fail('A solicitação mudou. Reabra a página antes de revisar.');$this->checkReferences($r,$d);$f->update($d+['revision'=>$f->revision+1]);$this->event($r,$f,'updated',$d);},3);return redirect()->route('followups.show',$id)->with('success','Preferências atualizadas.');}
 public function show(Request $r,int $id){$entry=$this->find($r,$id)->load(['appointment','events.actor']);$phone=app(AppointmentReminder::class)->phone($entry->customer->phone);$message='Olá! Aqui é da '.$r->user()->company->name.'. Podemos conversar sobre um horário para seu atendimento?';return $this->view('show',compact('entry','phone','message'));}
 public function contact(Request $r,int $id){$this->authorize($r);$d=$r->validate(['revision'=>'required|integer','request_id'=>'required|uuid','channel'=>['required',Rule::in(array_keys(Followups::CHANNELS))],'note'=>'required|string|min:3|max:500','acknowledge'=>'accepted']);DB::transaction(function()use($r,$id,$d){$this->lock($r);$f=$this->find($r,$id);$key=hash('sha256','contact|'.$f->company_id.'|'.$r->user()->id.'|'.$d['request_id']);if($old=Event::where('request_key',$key)->first()){abort_unless($old->followup_id===$id,409);return;}if(!$f->isOpen()||$f->revision!==(int)$d['revision'])$this->fail('A solicitação mudou. Reabra a página.');$f->update(['status'=>'contacted','last_contact_at'=>now(),'revision'=>$f->revision+1]);$this->event($r,$f,'contacted',['channel'=>$d['channel'],'note'=>$d['note']],$key);},3);return back()->with('success','Contato registrado. Nenhuma mensagem foi enviada pelo sistema.');}
 public function state(Request $r,int $id){$this->authorize($r);$d=$r->validate(['revision'=>'required|integer','action'=>'required|in:close,reopen','reason'=>'required|string|min:5|max:500']);DB::transaction(function()use($r,$id,$d){$this->lock($r);$f=$this->find($r,$id);if($f->revision!==(int)$d['revision'])$this->fail('A solicitação mudou. Reabra a página.');if($d['action']==='close'){if(!$f->isOpen())$this->fail('Só é possível encerrar uma solicitação aberta.');$f->update(['status'=>'closed','revision'=>$f->revision+1]);$this->event($r,$f,'closed',['reason'=>$d['reason']]);}else{if($f->status!=='closed')$this->fail('Só é possível reabrir uma solicitação encerrada.');$f->update(['status'=>'pending','revision'=>$f->revision+1]);$this->event($r,$f,'reopened',['reason'=>$d['reason']]);}},3);return back()->with('success','Situação atualizada.');}
}
